def calculadora(expressao):
    tokens = expressao.replace(" ", "")
    numero = 0
    operador = "+"
    for token in tokens:
        if token in "+-*/":
            operador = token
        else:
            valor = int(token)
            if operador == "+":
                numero += valor
            elif operador == "-":
                numero -= valor
            elif operador == "*":
                numero *= valor
            elif operador == "/":
                numero /= valor
    return numero

print(calculadora("3 + 4 * 2"))
